"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import "./expanding-gallery.css";

export interface GalleryImage {
  src: string;
  alt: string;
  title: string;
}

export function ExpandingGallery({ images }: { images: GalleryImage[] }) {
  const [active, setActive] = useState(0);
  const reduce = useReducedMotion();
  return (
    <div className="forme-gallery" aria-label="Image gallery">
      {images.map((image, i) => (
        <motion.button
          key={image.src}
          animate={{ flex: active === i ? 3.4 : 1 }}
          transition={{ duration: reduce ? 0 : 0.65, ease: [0.22, 1, 0.36, 1] }}
          onClick={() => setActive(i)}
          aria-pressed={active === i}
          aria-label={image.title}
        >
          <img src={image.src} alt={image.alt} loading="lazy" />
          <span>{image.title}</span>
        </motion.button>
      ))}
    </div>
  );
}

.forme-gallery {
  display: flex;
  gap: 8px;
  min-height: 250px;
  height: 100%;
  padding: 22px;
  box-sizing: border-box;
  background: #d7e2e9;
}
.forme-gallery button {
  position: relative;
  overflow: hidden;
  min-width: 0;
  padding: 0;
  border: 0;
  border-radius: 4px;
  cursor: pointer;
  background: #a2b6c4;
}
.forme-gallery img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.forme-gallery button:after {
  content: "";
  position: absolute;
  inset: 50% 0 0;
  background: linear-gradient(transparent, #0009);
}
.forme-gallery button > span {
  position: absolute;
  z-index: 1;
  bottom: 13px;
  left: 13px;
  right: 8px;
  color: white;
  font: 500 13px/1.3 sans-serif;
  text-align: left;
  opacity: 0;
  transition: opacity 0.2s;
}
.forme-gallery button[aria-pressed="true"] > span {
  opacity: 1;
}
.forme-gallery button:focus-visible {
  outline: 3px solid #2749ed;
  outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
  .forme-gallery button > span {
    transition: none;
  }
}
